// The benchmark's source: one entry per problem the founder flagged, with the recipe for its screens and the
// grader's key. `node make.mjs` turns it into ../cases.jsonl and screens.json (the input of shoot.mjs).
//
// Fields per entry: id, flags (lines of raw/flags.jsonl it merges), page, path (the address he was on, without the
// host), device, sha (the commit that was live when he wrote: the newest successful CI run before his message),
// screens (rebuilt pages, see shoot.mjs) or drawing (shots made by drawings.mjs), his_shot (his own whole-screen
// screenshot, used as a shot only when it shows the whole screen and nothing personal), crop (his own partial
// screenshot, kept for the grader only), group (several cases on one flaw), and key.
//
// key: flag (one neutral sentence), words (his words, trimmed to the flagged part), where, category, gt
// ("general" or "taste"), why, outside (true when only a reader who knows the market or the law could see it).

const g = (flag, words, where, category, gt, why, outside = false) => ({ flag, words, where, category, gt, why, outside });
const S = (name, path, steps, extra = {}) => ({ name, path, steps, ...extra });
const ADD_FUND_OPEN = [{ clickSel: "button:has-text('הוספת קרן שלא ברשימה')" }, { fill: ["שם הקרן", "iShares S&P 500 Swap UCITS ETF USD (Acc)"] },
  { fill: ["מספר נייר (לא חובה)", "IE00B5BMR087"] }, { select: ["סוג הקרן", "abroad"] }];
const ADD_FUND = [...ADD_FUND_OPEN, { fill: ["דמי ניהול שנתיים", "0.05"] }, { click: "שמירה במכשיר" }];
const ADD_INDEX = [{ click: "אחר" }, { fill: ["שם המדד", "test"] }, { clickOpt: "המשך" }, { clickOpt: "לא" }, { click: "שמירה במכשיר" }];
const IDLE = [{ fill: ["כמה יש בעו״ש", "20000"] }, { fill: ["כמה חייב להישאר זמין מיד", "5000"] }, { press: "Tab" }];
const DRAW = "Drawings made by the site's designers, shown as options side by side; any mark that one option is recommended is theirs.";

// A saved goal with a securities account in its comparison, for the pages that need one (neutral figures, not his).
const goalState = (goals) => ({ "mekor.v2.state": JSON.stringify({ version: 3, goals: goals.map((x, i) => ({
  id: "g" + i, name: x.name || "", preset: x.preset || "lump-sum",
  horizonYears: { value: x.years, entered: true }, amountNow: { value: x.now, entered: true }, monthly: { value: x.monthly ?? 0, entered: true },
  available: { value: null, entered: false }, availableFrom: null, anytime: { value: false, entered: false },
  profile: { age: null, employment: null, salary: null, pension: { employer: null, employee: null }, hishtalmut: { employer: null, employee: null, yearly: null }, hasPension: null, hasHishtalmut: null },
  assumptions: { return: x.ret ?? null, inflation: null, insurance: null, acceptedFall: null }, exposures: {}, order: i })),
  inputs: {}, holdings: [], uncatalogued: [], imports: [], savedComparisons: [], currentId: "g0" }) });

